import 'package:flutter/material.dart';
import '../api.dart';
import '../main.dart';
import 'marketplace_models.dart';
import 'provider_detail_screen.dart';
class MarketplaceScreen extends StatefulWidget { const MarketplaceScreen({super.key}); @override State<MarketplaceScreen> createState() => _MarketplaceScreenState(); }
class _MarketplaceScreenState extends State<MarketplaceScreen> { final api = JopetsApi(); List<MarketplaceProvider> products = []; String? error; bool loading = true; @override void initState() { super.initState(); load(); } Future<void> load() async { try { final rows = await api.marketplaceProducts(); if (mounted) setState(() { products = rows.map(MarketplaceProvider.fromApi).toList(); error = null; }); } catch (e) { if (mounted) setState(() => error = e.toString()); } finally { if (mounted) setState(() => loading = false); } } @override Widget build(BuildContext context) => Scaffold(backgroundColor: const Color(0xFFF7F8FA), appBar: AppBar(backgroundColor: navy, foregroundColor: Colors.white, title: const Text('Servicios'), actions: [IconButton(onPressed: load, icon: const Icon(Icons.refresh))]), body: loading ? const Center(child: CircularProgressIndicator()) : error != null ? Center(child: Text(error!)) : products.isEmpty ? const Center(child: Text('El servidor no devolvió servicios.')) : ListView.builder(padding: const EdgeInsets.all(16), itemCount: products.length, itemBuilder: (_, index) { final item = products[index]; return Card(child: ListTile(leading: const CircleAvatar(child: Icon(Icons.business)), title: Text(item.name), subtitle: Text('${item.price} ${item.currency}'), trailing: const Icon(Icons.chevron_right), onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => ProviderDetailScreen(productId: item.id))))); })); }
